window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-70295554985bb1df"]={"versions": [{"id": "FIG-70295554985bb1df", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.</li>\n<li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.</li>\n<li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify \"Sychronize Mode\"</code>.</li>\n<li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:</li>\n<li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.</li>\n<li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.</li>\n<li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.</li>\n<li><strong>Pseudozustände & Endzustände:</strong></li>\n<li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.</li>\n<li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.</li>\n<li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.</li>\n<li><strong>Schnittstellen & Funktionsaufrufe (Trigger/Aktionen):</strong></li>\n<li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.</li>\n<li>Notifications: <code>/Notify \"Network Mode\"</code>, <code>/Nm_BusSleepMode</code>.</li>\n<li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.</li>\n<li><strong>Statusvariablen & Zähler:</strong></li>\n<li><code>FrNm_NetworkRequest</code> (BOOLEAN)</li>\n<li><code>FrNm_RepeatMessage</code> (BOOLEAN)</li>\n<li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)</li>\n<li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.</li>\n<li><strong>Kommentar-Notizen:</strong></li>\n<li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).</li>\n<li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n<li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.</li>\n<li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.</li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.</li>\n<li><strong>Synchronisation:</strong></li>\n<li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.</li>\n<li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify \"Network Mode\"</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.</li>\n<li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.</li>\n<li><strong>Network Mode Zyklen & Zustandswechsel:</strong></li>\n<li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.</li>\n<li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):</li>\n<li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.</li>\n<li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.</li>\n<li>In <code>Normal Operation</code>:</li>\n<li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.</li>\n<li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>In <code>Ready Sleep</code>:</li>\n<li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.</li>\n<li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.</li>\n<li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.</li>\n<li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.</li>\n<li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:</li>\n<li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.</li>\n<li><strong>Herunterfahren:</strong></li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.</li>\n<li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.</li>\n<li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.</li>\n<li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.</li>\n</ul>"}, {"id": "FIG-618a12c348b10353", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.</li>\n<li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.</li>\n<li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify \"Sychronize Mode\"</code>.</li>\n<li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:</li>\n<li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.</li>\n<li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.</li>\n<li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.</li>\n<li><strong>Pseudozustände & Endzustände:</strong></li>\n<li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.</li>\n<li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.</li>\n<li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.</li>\n<li><strong>Schnittstellen & Funktionsaufrufe (Trigger/Aktionen):</strong></li>\n<li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.</li>\n<li>Notifications: <code>/Notify \"Network Mode\"</code>, <code>/Nm_BusSleepMode</code>.</li>\n<li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.</li>\n<li><strong>Statusvariablen & Zähler:</strong></li>\n<li><code>FrNm_NetworkRequest</code> (BOOLEAN)</li>\n<li><code>FrNm_RepeatMessage</code> (BOOLEAN)</li>\n<li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)</li>\n<li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.</li>\n<li><strong>Kommentar-Notizen:</strong></li>\n<li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).</li>\n<li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n<li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.</li>\n<li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.</li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.</li>\n<li><strong>Synchronisation:</strong></li>\n<li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.</li>\n<li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify \"Network Mode\"</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.</li>\n<li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.</li>\n<li><strong>Network Mode Zyklen & Zustandswechsel:</strong></li>\n<li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.</li>\n<li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):</li>\n<li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.</li>\n<li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.</li>\n<li>In <code>Normal Operation</code>:</li>\n<li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.</li>\n<li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>In <code>Ready Sleep</code>:</li>\n<li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.</li>\n<li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.</li>\n<li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.</li>\n<li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.</li>\n<li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:</li>\n<li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.</li>\n<li><strong>Herunterfahren:</strong></li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.</li>\n<li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.</li>\n<li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.</li>\n<li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.</li>\n</ul>"}, {"id": "FIG-049daa5ed1aeb697", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.</li>\n<li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.</li>\n<li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify \"Sychronize Mode\"</code>.</li>\n<li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:</li>\n<li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.</li>\n<li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.</li>\n<li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.</li>\n<li><strong>Pseudozustände & Endzustände:</strong></li>\n<li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.</li>\n<li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.</li>\n<li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.</li>\n<li><strong>Schnittstellen & Funktionsaufrufe (Trigger/Aktionen):</strong></li>\n<li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.</li>\n<li>Notifications: <code>/Notify \"Network Mode\"</code>, <code>/Nm_BusSleepMode</code>.</li>\n<li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.</li>\n<li><strong>Statusvariablen & Zähler:</strong></li>\n<li><code>FrNm_NetworkRequest</code> (BOOLEAN)</li>\n<li><code>FrNm_RepeatMessage</code> (BOOLEAN)</li>\n<li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)</li>\n<li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.</li>\n<li><strong>Kommentar-Notizen:</strong></li>\n<li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).</li>\n<li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n<li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.</li>\n<li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.</li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.</li>\n<li><strong>Synchronisation:</strong></li>\n<li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.</li>\n<li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify \"Network Mode\"</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.</li>\n<li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.</li>\n<li><strong>Network Mode Zyklen & Zustandswechsel:</strong></li>\n<li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.</li>\n<li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):</li>\n<li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.</li>\n<li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.</li>\n<li>In <code>Normal Operation</code>:</li>\n<li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.</li>\n<li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>In <code>Ready Sleep</code>:</li>\n<li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.</li>\n<li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.</li>\n<li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.</li>\n<li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.</li>\n<li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:</li>\n<li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.</li>\n<li><strong>Herunterfahren:</strong></li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.</li>\n<li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.</li>\n<li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.</li>\n<li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.</li>\n</ul>"}, {"id": "FIG-17c44f137303b916", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.</li>\n<li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.</li>\n<li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify \"Sychronize Mode\"</code>.</li>\n<li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:</li>\n<li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.</li>\n<li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.</li>\n<li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.</li>\n<li><strong>Pseudozustände & Endzustände:</strong></li>\n<li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.</li>\n<li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.</li>\n<li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.</li>\n<li><strong>Schnittstellen & Funktionsaufrufe (Trigger/Aktionen):</strong></li>\n<li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.</li>\n<li>Notifications: <code>/Notify \"Network Mode\"</code>, <code>/Nm_BusSleepMode</code>.</li>\n<li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.</li>\n<li><strong>Statusvariablen & Zähler:</strong></li>\n<li><code>FrNm_NetworkRequest</code> (BOOLEAN)</li>\n<li><code>FrNm_RepeatMessage</code> (BOOLEAN)</li>\n<li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)</li>\n<li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.</li>\n<li><strong>Kommentar-Notizen:</strong></li>\n<li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).</li>\n<li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n<li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.</li>\n<li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.</li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.</li>\n<li><strong>Synchronisation:</strong></li>\n<li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.</li>\n<li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify \"Network Mode\"</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.</li>\n<li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.</li>\n<li><strong>Network Mode Zyklen & Zustandswechsel:</strong></li>\n<li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.</li>\n<li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):</li>\n<li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.</li>\n<li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.</li>\n<li>In <code>Normal Operation</code>:</li>\n<li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.</li>\n<li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>In <code>Ready Sleep</code>:</li>\n<li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.</li>\n<li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.</li>\n<li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.</li>\n<li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.</li>\n<li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:</li>\n<li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.</li>\n<li><strong>Herunterfahren:</strong></li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.</li>\n<li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.</li>\n<li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.</li>\n<li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.</li>\n</ul>"}, {"id": "FIG-e830d9db65f376d1", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.</li>\n<li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>entry / entry FrNm_NetworkRequest = FALSE FrNm_RepeatMessage = FALSE</code>.</li>\n<li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>entry / entry Notify \"Sychronize Mode\"</code>.</li>\n<li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:</li>\n<li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>entry / entry Start RepeateMessage Timer</code>.</li>\n<li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.</li>\n<li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.</li>\n<li><strong>Pseudozustände & Endzustände:</strong></li>\n<li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.</li>\n<li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.</li>\n<li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.</li>\n<li><strong>Schnittstellen & Funktionsaufrufe (Trigger/Aktionen):</strong></li>\n<li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.</li>\n<li>Notifications: <code>/Notify \"Network Mode\"</code>, <code>/Nm_BusSleepMode</code>.</li>\n<li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.</li>\n<li><strong>Statusvariablen & Zähler:</strong></li>\n<li><code>FrNm_NetworkRequest</code> (BOOLEAN)</li>\n<li><code>FrNm_RepeatMessage</code> (BOOLEAN)</li>\n<li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)</li>\n<li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.</li>\n<li><strong>Kommentar-Notizen:</strong></li>\n<li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).</li>\n<li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n<li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.</li>\n<li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.</li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.</li>\n<li><strong>Synchronisation:</strong></li>\n<li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.</li>\n<li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify \"Network Mode\"</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.</li>\n<li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.</li>\n<li><strong>Network Mode Zyklen & Zustandswechsel:</strong></li>\n<li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.</li>\n<li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):</li>\n<li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.</li>\n<li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.</li>\n<li>In <code>Normal Operation</code>:</li>\n<li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.</li>\n<li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.</li>\n<li>In <code>Ready Sleep</code>:</li>\n<li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.</li>\n<li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.</li>\n<li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.</li>\n<li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.</li>\n<li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:</li>\n<li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.</li>\n<li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.</li>\n<li><strong>Herunterfahren:</strong></li>\n<li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.</li>\n<li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.</li>\n<li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.</li>\n<li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.</li>\n</ul>"}], "trans": [{"from": "FIG-70295554985bb1df", "to": "FIG-618a12c348b10353", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-618a12c348b10353", "to": "FIG-049daa5ed1aeb697", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-049daa5ed1aeb697", "to": "FIG-17c44f137303b916", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-17c44f137303b916", "to": "FIG-e830d9db65f376d1", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Zustände <code>Bus Sleep Mode</code>, <code>Synchronize</code> und <code>Repeat Message</code>: Das Präfix <code>+ </code> vor den <code>entry / entry</code>-Aktionen entfällt.</li>\n</ul>"}]};
